// The REST requests capture_rest.mjs sends to the emulator, grouped by what they check. Each
// group runs on its own namespace, its cases in order: a case sees what the ones before it
// wrote. See capture_rest.mjs for the fields of a case.

const get = (name, p, o = {}) => ({name, method: 'GET', path: p, ...o});
const put = (name, p, json, o = {}) => ({name, method: 'PUT', path: p, json, ...o});
const patch = (name, p, json, o = {}) => ({name, method: 'PATCH', path: p, json, ...o});
const post = (name, p, json, o = {}) => ({name, method: 'POST', path: p, json, ...o});
const del = (name, p, o = {}) => ({name, method: 'DELETE', path: p, ...o});
const raw = (name, method, p, body, o = {}) => ({name, method, path: p, body, ...o});
const q = s => encodeURIComponent(JSON.stringify(s));

const etagOn = {'X-Firebase-ETag': 'true'};
const wrongEtag = 'AAAAAAAAAAAAAAAAAAAAAAAAAAA=';

// deepPath builds /s1/s2/.../sn.json, n segments deep.
const deepPath = n => '/' + Array.from({length: n}, (_, i) => 's' + i).join('/') + '.json';
// nested builds an object n levels deep with a leaf at the bottom.
const nested = n => { let v = 1; for (let i = 0; i < n; i++) v = {k: v}; return v; };

